// Candidate Topic Input with dynamic execution timestamp
const timestamp = Date.now();
return {
  title: 'The Voyager Interstellar Anomaly: Unexplained Telemetry',
  topic: 'Voyager 1 thruster and telemetry anomalies in interstellar space',
  category: 'science',
  channelName: 'The 10min Explosion',
  idempotencyKey: 'voyager-run-' + timestamp,
  summary: 'NASA engineers investigated unexpected telemetry data from Voyager 1 instruments outside the heliosphere.',
  source_url: 'https://phys.org/news/2024-voyager-space-telemetry.html',
  keywords: ['voyager', 'nasa', 'interstellar', 'space', 'telemetry', 'propulsion']
};

const input = $input.first().json;

if (!input.title || typeof input.title !== 'string' || input.title.trim().length < 3) {
  throw new Error('Validation Error: Candidate title is required and must be at least 3 characters.');
}

if (!input.topic || typeof input.topic !== 'string' || input.topic.trim().length < 2) {
  throw new Error('Validation Error: Candidate topic is required.');
}

return {
  title: input.title.trim(),
  topic: input.topic.trim(),
  category: input.category || 'general',
  channelName: input.channelName || 'The 10min Explosion',
  idempotencyKey: input.idempotencyKey || null,
  metadata: {
    summary: input.summary || '',
    source_url: input.source_url || null,
    keywords: input.keywords || [],
    category: input.category || 'general'
  }
};

