// Extract data from previous nodes in the execution trace
const project = $input.first().json.project;
const researchData = $('Execute Research Pipeline').first().json;
const dossier = researchData.dossier || {};
const topicScore = researchData.topicScore || {};

return {
  success: true,
  project: {
    id: project.id,
    title: project.title,
    topic: project.topic,
    channelName: project.channelName,
    status: project.status,
    version: project.version,
    startedAt: project.startedAt,
    metadata: project.metadata
  },
  research: {
    overallScore: topicScore.overall_score,
    eligibility: researchData.eligibilityStatus,
    verifiedFactsCount: dossier.verified_facts?.length || 0,
    disputedClaimsCount: dossier.disputed_claims?.length || 0,
    timelineEventsCount: dossier.timeline?.length || 0,
    sourcesAnalyzed: researchData.sourceDocumentsCount || 0,
    suggestedExplainerAngles: dossier.suggested_explainer_angles || []
  },
  dossierSummary: {
    coreEntity: dossier.core_entity,
    coreNarrative: dossier.core_narrative,
    keyThemes: dossier.key_themes
  },
  dossier: dossier
};

// Seamlessly extract project and verified research dossier from Phase 2
const researchNode = $('Execute Research Pipeline').first().json;
const project = $('Verify Current Project State').first().json.project;
const dossier = researchNode.dossier;

if (!dossier || typeof dossier !== 'object') {
  throw new Error('Validation Error: Phase 2 research dossier is missing.');
}

if (dossier.eligibility_status !== 'READY_FOR_REVIEW') {
  throw new Error(`Eligibility Error: Dossier status is '${dossier.eligibility_status}'. Topic must be READY_FOR_REVIEW to generate script.`);
}

return {
  projectId: project.id,
  topic: project.topic,
  category: researchNode.category || 'science',
  dossier: dossier
};
